const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const grafton = ee.Geometry.Point([152.932, -29.681]);
  const canberra = ee.Geometry.Point([149.1300, -35.2809]);

  const startDate = '2020-01-15';
  const endDate = '2020-01-21';

  // 2. Data Acquisition
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .select('precipitation');

  const collectionSize = chirps.size().getInfo();
  console.log(`Images in date range: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Calculate total rainfall for each location
  const graftonRainfall = chirps.sum().reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: grafton,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation');

  const canberraRainfall = chirps.sum().reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: canberra,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation');

  // 4. Get values and validate
  const graftonVal = graftonRainfall.getInfo();
  const canberraVal = canberraRainfall.getInfo();

  console.log(`Grafton total rainfall: ${graftonVal?.toFixed(2)} mm`);
  console.log(`Canberra total rainfall: ${canberraVal?.toFixed(2)} mm`);

  // 5. Validation & Final Answer
  if (graftonVal === null || canberraVal === null || 
      isNaN(graftonVal) || isNaN(canberraVal)) {
    console.log("<answer>C3</answer>");
  } else if (graftonVal > canberraVal) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
